// Main dynamic translator helper
export function t(key: string, locale: string): string {
  const currentLocale = (locale || 'en').toLowerCase();
  
  // Try exact key matching in UI translation database
  if (uiTranslations[key]) {
    return uiTranslations[key][currentLocale] || uiTranslations[key]['en'] || key;
  }
  
  // Try exact category translating
  if (categoryTranslations[key]) {
    return categoryTranslations[key][currentLocale] || categoryTranslations[key]['en'] || key;
  }

  return key;
}

// Translate dynamic category label
export function translateCategory(slug: string, locale: string): string {
  return categoryTranslations[slug]?.[locale] || categoryTranslations[slug]?.[locale.split('-')[0]] || categoryTranslations[slug]?.['en'] || slug;
}

// Translate dynamic unit label
export function translateUnit(key: string, locale: string, defaultLabel: string): string {
  const currentLocale = (locale || 'en').toLowerCase();
  const cleanKey = key.toLowerCase().trim();
  
  if (unitTranslations[cleanKey]) {
    return unitTranslations[cleanKey][currentLocale] || unitTranslations[cleanKey]['en'] || defaultLabel;
  }
  
  // Fallback to base language mapping (e.g. 'zh-cn' -> 'zh')
  const baseLoc = currentLocale.split('-')[0];
  if (unitTranslations[cleanKey] && unitTranslations[cleanKey][baseLoc]) {
    return unitTranslations[cleanKey][baseLoc];
  }
  
  return defaultLabel;
}

// Helper to determine if a locale uses Right-to-Left writing orientation
export function isRtlLocale(locale: string): boolean {
  return RTL_LOCALES.has(locale.toLowerCase().split('-')[0]);
}

// Build canonical/alternative URL listings for alternate language indexing tags
export function getAlternateUrls(path: string): Array<{ locale: string; href: string }> {
  // Strip existing locale segment
  let cleanPath = path;
  const segments = path.split('/').filter(Boolean);
  if (segments.length > 0 && locales.includes(segments[0] as any)) {
    cleanPath = '/' + segments.slice(1).join('/');
  }
  
  // Make sure it starts with a single slash
  if (!cleanPath.startsWith('/')) {
    cleanPath = '/' + cleanPath;
  }

  const alternates: Array<{ locale: string; href: string }> = [];
  
  locales.forEach(loc => {
    const prefix = loc === 'en' ? '' : '/' + loc;
    // Prevent double slashes
    let href = prefix + cleanPath;
    if (href.endsWith('/') && href.length > 1) {
      href = href.slice(0, -1);
    }
    alternates.push({ locale: loc, href });
  });

  return alternates;
}

// Helper to translate popular converter routes (like inches-to-cm)
export function translatePopularRoute(slug: string, locale: string, defaultTitle: string): string {
  const parts = slug.split('-to-');
  if (parts.length === 2) {
    const fromKey = parts[0];
    const toKey = parts[1];
    
    // Map popular keys
    const keyMap: Record<string, string> = {
      'inches': 'inch', 'inch': 'inch',
      'cm': 'centimeter', 'centimeter': 'centimeter',
      'feet': 'foot', 'foot': 'foot',
      'meters': 'meter', 'meter': 'meter',
      'km': 'kilometer', 'kilometer': 'kilometer',
      'miles': 'mile', 'mile': 'mile',
      'kg': 'kilogram', 'kilogram': 'kilogram',
      'pounds': 'pound', 'pound': 'pound',
      'celsius': 'celsius', 'fahrenheit': 'fahrenheit',
      'liters': 'liter', 'liter': 'liter',
      'gallons': 'gallon-us', 'gallon': 'gallon-us',
      'mb': 'megabyte', 'megabyte': 'megabyte',
      'gb': 'gigabyte', 'gigabyte': 'gigabyte',
      'tb': 'terabyte', 'terabyte': 'terabyte',
      'binary': 'binary', 'decimal': 'decimal'
    };
    
    const fromUnitKey = keyMap[fromKey] || fromKey;
    const toUnitKey = keyMap[toKey] || toKey;
    
    const fromName = translateUnit(fromUnitKey, locale, fromKey);
    const toName = translateUnit(toUnitKey, locale, toKey);
    
    const toWord = t('card_to', locale).toLowerCase();
    
    if (locale === 'ja') {
      return `${fromName}から${toName}`;
    }
    if (locale === 'hi') {
      return `${fromName} से ${toName}`;
    }
    if (locale === 'ar') {
      return `تحويل ${fromName} إلى ${toName}`;
    }
    return `${fromName} ${toWord} ${toName}`;
  }
  return defaultTitle;
}
